import React, { useState, useEffect } from 'react';
import playSound from '../utils/soundManager';

const ControllerSettings = ({ isActive }) => {
  const [selectedController, setSelectedController] = useState('xbox');

  useEffect(() => {
    // Load saved controller preference
    const saved = localStorage.getItem('controllerType');
    if (saved) {
      setSelectedController(saved);
    }
  }, []);

  useEffect(() => {
    // Listen for save event from Settings
    const handleSave = () => {
      if (isActive) {
        localStorage.setItem('controllerType', selectedController);
        console.log('Controller preference saved:', selectedController);
      }
    };
    window.addEventListener('dashboard-save-settings', handleSave);
    return () => window.removeEventListener('dashboard-save-settings', handleSave);
  }, [isActive, selectedController]);

  const handleControllerSelect = (type) => {
    playSound('select');
    setSelectedController(type);
    localStorage.setItem('controllerType', type);
    // Dispatch event to update button prompts throughout the app
    window.dispatchEvent(new CustomEvent('controllerTypeChanged', { detail: { controllerType: type } }));
  };

  const getButtonColor = (controllerType, button) => {
    const colors = {
      xbox: {
        'A': '#107C10', // Green
        'B': '#E81123', // Red
        'X': '#0078D4', // Blue
        'Y': '#FFB900', // Yellow
        'LB': '#8E8E8E',
        'RB': '#8E8E8E',
        'LT': '#8E8E8E',
        'RT': '#8E8E8E'
      },
      playstation: {
        '✕': '#0070CC', // Blue (X)
        '○': '#CD2A2A', // Proper Red (Circle)
        '□': '#E91E63', // Pink (Square)
        '△': '#27AE60', // Green (Triangle)
        'L1': '#8E8E8E',
        'R1': '#8E8E8E',
        'L2': '#8E8E8E',
        'R2': '#8E8E8E'
      },
      nintendo: {
        'A': '#2C2C2C', // Black
        'B': '#2C2C2C', // Black
        'X': '#2C2C2C', // Black
        'Y': '#2C2C2C', // Black
        'L': '#8E8E8E',
        'R': '#8E8E8E',
        'ZL': '#8E8E8E',
        'ZR': '#8E8E8E'
      },
      generic: {
        '1': '#8E8E8E',
        '2': '#8E8E8E',
        '3': '#8E8E8E',
        '4': '#8E8E8E',
        'L1': '#8E8E8E',
        'R1': '#8E8E8E',
        'L2': '#8E8E8E',
        'R2': '#8E8E8E'
      }
    };
    return colors[controllerType]?.[button] || '#8E8E8E';
  };

  const controllers = [
    {
      id: 'xbox',
      name: 'Xbox',
      buttons: ['A', 'B', 'X', 'Y', 'LB', 'RB', 'LT', 'RT']
    },
    {
      id: 'playstation',
      name: 'PlayStation',
      buttons: ['✕', '○', '□', '△', 'L1', 'R1', 'L2', 'R2']
    },
    {
      id: 'nintendo',
      name: 'Nintendo',
      buttons: ['A', 'B', 'X', 'Y', 'L', 'R', 'ZL', 'ZR']
    },
    {
      id: 'generic',
      name: 'Generic',
      buttons: ['1', '2', '3', '4', 'L1', 'R1', 'L2', 'R2']
    }
  ];

  return (
    <div style={{
      padding: '30px',
      color: 'white',
      maxWidth: '900px',
      margin: '0 auto'
    }}>
      <h2 style={{
        fontSize: '1.8rem',
        fontWeight: '700',
        marginBottom: '10px',
        color: '#fff'
      }}>
        Controller Settings
      </h2>
      <p style={{
        fontSize: '0.95rem',
        color: 'rgba(255,255,255,0.7)',
        marginBottom: '30px',
        lineHeight: '1.6'
      }}>
        Select your primary controller type to customize button prompts throughout the app.
      </p>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, 1fr)',
        gap: '20px',
        marginTop: '30px'
      }}>
        {controllers.map((controller) => (
          <div
            key={controller.id}
            onClick={() => handleControllerSelect(controller.id)}
            style={{
              background: 'rgba(255,255,255,0.05)',
              border: selectedController === controller.id
                ? '2px solid rgba(255,255,255,0.3)'
                : '2px solid rgba(255,255,255,0.1)',
              borderRadius: '15px',
              padding: '25px',
              cursor: 'pointer',
              transition: 'all 0.3s',
              position: 'relative',
              overflow: 'hidden'
            }}
            onMouseEnter={(e) => {
              if (selectedController !== controller.id) {
                e.currentTarget.style.background = 'rgba(255,255,255,0.1)';
                e.currentTarget.style.transform = 'translateY(-5px)';
              }
            }}
            onMouseLeave={(e) => {
              if (selectedController !== controller.id) {
                e.currentTarget.style.background = 'rgba(255,255,255,0.05)';
                e.currentTarget.style.transform = 'translateY(0)';
              }
            }}
          >
            {selectedController === controller.id && (
              <div style={{
                position: 'absolute',
                top: '10px',
                right: '10px',
                background: 'transparent',
                color: '#107C10',
                padding: '5px',
                borderRadius: '50%',
                fontSize: '2rem',
                fontWeight: '700',
                lineHeight: '1'
              }}>
                ✓
              </div>
            )}

            <h3 style={{
              fontSize: '1.4rem',
              fontWeight: '700',
              marginBottom: '20px',
              color: '#fff'
            }}>
              {controller.name}
            </h3>

            <div style={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: '8px'
            }}>
              {controller.buttons.map((button, idx) => {
                const isPlayStation = controller.id === 'playstation';
                const isXbox = controller.id === 'xbox';
                const isNintendo = controller.id === 'nintendo';
                const buttonColor = getButtonColor(controller.id, button);
                
                // Xbox: gradient background with colored text
                if (isXbox) {
                  return (
                    <div
                      key={idx}
                      style={{
                        background: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 50%, #0a0a0a 100%)',
                        padding: '8px 14px',
                        borderRadius: '50%',
                        fontSize: '1.2rem',
                        fontWeight: '700',
                        color: buttonColor,
                        minWidth: '40px',
                        minHeight: '40px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        border: '2.5px solid #2a2a2a',
                        boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05), inset 0 -1px 2px rgba(0,0,0,0.5)',
                        textShadow: `0 1px 3px ${buttonColor}80`
                      }}
                    >
                      {button}
                    </div>
                  );
                }
                
                // PlayStation: black background with colored symbols only
                if (isPlayStation) {
                  return (
                    <div
                      key={idx}
                      style={{
                        background: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 50%, #0a0a0a 100%)',
                        padding: '8px 14px',
                        borderRadius: '50%',
                        fontSize: '1.2rem',
                        fontWeight: '700',
                        color: buttonColor,
                        minWidth: '40px',
                        minHeight: '40px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        border: '2.5px solid #2a2a2a',
                        boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.05), inset 0 -1px 2px rgba(0,0,0,0.5)',
                        textShadow: `0 1px 3px ${buttonColor}80`
                      }}
                    >
                      {button}
                    </div>
                  );
                }
                
                // Nintendo: solid black with white text
                if (isNintendo) {
                  return (
                    <div
                      key={idx}
                      style={{
                        background: 'linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 50%, #1a1a1a 100%)',
                        padding: '8px 14px',
                        borderRadius: '50%',
                        fontSize: '1.1rem',
                        fontWeight: '700',
                        color: '#ffffff',
                        minWidth: '40px',
                        minHeight: '40px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        border: '2.5px solid #3a3a3a',
                        boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.08), inset 0 -1px 2px rgba(0,0,0,0.5)',
                        textShadow: '0 1px 2px rgba(0,0,0,0.8)'
                      }}
                    >
                      {button}
                    </div>
                  );
                }
                
                // Generic: neutral gray with white text
                const isGeneric = controller.id === 'generic';
                if (isGeneric) {
                  return (
                    <div
                      key={idx}
                      style={{
                        background: 'linear-gradient(135deg, #3a3a3a 0%, #4a4a4a 50%, #3a3a3a 100%)',
                        padding: '8px 14px',
                        borderRadius: '50%',
                        fontSize: '1.1rem',
                        fontWeight: '700',
                        color: '#ffffff',
                        minWidth: '40px',
                        minHeight: '40px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        border: '2.5px solid #5a5a5a',
                        boxShadow: '0 3px 8px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.1), inset 0 -1px 2px rgba(0,0,0,0.5)',
                        textShadow: '0 1px 2px rgba(0,0,0,0.8)'
                      }}
                    >
                      {button}
                    </div>
                  );
                }
                
                return null;
              })}
            </div>
          </div>
        ))}
      </div>

      <div style={{
        marginTop: '40px',
        padding: '20px',
        background: 'rgba(255,255,255,0.05)',
        borderRadius: '12px',
        border: '1px solid rgba(255,255,255,0.1)'
      }}>
        <h4 style={{
          fontSize: '1.1rem',
          fontWeight: '600',
          marginBottom: '10px',
          color: '#fff'
        }}>
          Note
        </h4>
        <p style={{
          fontSize: '0.9rem',
          color: 'rgba(255,255,255,0.7)',
          lineHeight: '1.6'
        }}>
          Button prompts throughout the app will update to match your selected controller type. 
          Don't forget to click the <strong>Save (X)</strong> button in the top-right corner to apply your changes.
        </p>
      </div>
    </div>
  );
};

export default ControllerSettings;
