import React, { useState, useEffect, useRef } from 'react';
import { useGamepad } from '../context/GamepadContext';
import { useTheme } from '../context/ThemeContext';
import playSound from '../utils/soundManager';
import { AlertCircle, Volume2, Globe, Palette, Cpu, User, Image, Gamepad2, Info, Users } from 'lucide-react';
import GamepadDiagnostic from './GamepadDiagnostic';
import LanguageSettings from './LanguageSettings';
import CoreSettings from './CoreSettings';
import ColorSettings from './ColorSettings';
import BackgroundSettings from './BackgroundSettings';
import AccountSettings from './AccountSettings';
import ControllerSettings from './ControllerSettings';
import PortsSettings from './PortsSettings';
import HelpSettings from './HelpSettings';
import AboutSettings from './AboutSettings';
import ContributorsSettings from './ContributorsSettings';
import '../styles/Settings.css';

const HELP_ICON_SRC = '/assets/for-app/Help.webp';

const HelpIcon = ({ size = 20, className = '' }) => (
  <img
    src={HELP_ICON_SRC}
    alt="Help"
    className={`settings-sidebar-icon image-icon ${className}`}
    style={{ width: size, height: size }}
  />
);

const Settings = ({ isActive, onBack, userProfile, isLoggedIn, onLogout }) => {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [activePanel, setActivePanel] = useState(null); // Default to null (Sidebar active)
  const [isSaving, setIsSaving] = useState(false);
  const [isDirty, setIsDirty] = useState(false);
  const [showExitPrompt, setShowExitPrompt] = useState(false);
  const [saveStatus, setSaveStatus] = useState(''); // 'saving', 'saved'
  const [countryCode, setCountryCode] = useState('AU');
  const [controllerType, setControllerType] = useState(localStorage.getItem('controllerType') || 'xbox');
  const listRef = useRef(null);
  const { onPress: onGamepadPress } = useGamepad();
  const { changeTheme } = useTheme();

  // Load initial country code
  useEffect(() => {
    const loadCountry = async () => {
      try {
        const { settingsApi } = await import('../services/apiServices');
        const saved = await settingsApi.get();
        if (saved && saved.country) setCountryCode(saved.country);
      } catch (e) {
        console.error("Settings: Failed to load country:", e);
      }
    };
    loadCountry();
  }, []);

  // Listen for controller type changes
  useEffect(() => {
    const handleControllerChange = (event) => {
      setControllerType(event.detail.controllerType);
    };
    window.addEventListener('controllerTypeChanged', handleControllerChange);
    return () => window.removeEventListener('controllerTypeChanged', handleControllerChange);
  }, []);

  const dynamicSettingsItems = [
    { id: 'account', label: 'Account Settings', icon: User, description: 'Manage your primary Discord profile, security tokens, and session status.' },
    { id: 'controller', label: 'Controller', icon: Gamepad2, description: 'Select your primary controller type (Xbox, PlayStation, Nintendo) to customize button prompts throughout the app.' },
    { id: 'core', label: 'Configuration Settings', icon: AlertCircle, description: 'Configure emulator settings including video, audio, input, and core management options.' },
    { id: 'country', label: 'Country', icon: Globe, description: 'Change the display country/region for the dashboard interface.', badge: countryCode },
    { id: 'color', label: 'Hover Color', icon: Palette, description: 'Change the global accent color for the dashboard interface.' },
    { id: 'background', label: 'Background', icon: Image, description: 'Set a custom wallpaper image for your dashboard.' },
    { id: 'help', label: 'Help & Support', icon: HelpIcon, description: 'Access the Discord bugs channel directly from the dashboard to report issues or ask for support.' },
    { id: 'contributors', label: 'Contributors', icon: Users, description: 'View the team members and contributors who built Vortex Prime.' },
    { id: 'about', label: 'About', icon: Info, description: 'Learn about Vortex Prime, its features, and the creator behind the project.' },
  ];

  const handleSave = () => {
    playSound('select');
    setIsSaving(true);
    setSaveStatus('saving');

    // Trigger save on active sub-components
    window.dispatchEvent(new Event('dashboard-save-settings'));

    // Sequence: Saving (2s) -> Ready to Restart
    setTimeout(() => {
      setSaveStatus('saved');
      setIsDirty(false);
      playSound('panelUnfold'); // Success sound
    }, 2000);
  };

  const executeBackout = () => {
    playSound('back');
    onBack();
  };

  const attemptExit = () => {
    if (activePanel) {
      playSound('back');
      setActivePanel(null);
    } else {
      if (isDirty) {
        playSound('error');
        setShowExitPrompt(true);
      } else {
        executeBackout();
      }
    }
  };

  const handleRestart = async () => {
    playSound('select');
    try {
      if (window.__TAURI__) {
        const { relaunch } = await import('@tauri-apps/plugin-process');
        await relaunch();
      } else {
        console.log("Web Preview: App restart simulated.");
        window.location.reload();
      }
    } catch (e) {
      console.error("Restart failed:", e);
      setIsSaving(false);
      setSaveStatus('');
    }
  };

  const handleDefault = () => {
    playSound('select');
    const currentId = activePanel || dynamicSettingsItems[selectedIndex].id;
    if (currentId === 'color') {
      changeTheme('#107C10');
      setIsDirty(true);
    } else if (currentId === 'country') {
      setCountryCode('AU');
      setIsDirty(true);
    } else {
      console.log("Restored to default");
      // Could add a similar overlay for restore if desired
    }
  };

  useEffect(() => {
    if (!isActive) {
      setActivePanel(null);
    }
  }, [isActive]);

  useEffect(() => {
    if (activePanel === null) {
      // ...
    }
  }, [activePanel]);

  useEffect(() => {
    if (!isActive || isSaving) return; // Block input during saving

    const handleKeyDown = (e) => {
      // If saving or prompting to exit, block background keys
      if (isSaving || showExitPrompt) {
        e.preventDefault();
        e.stopImmediatePropagation();
        
        // Handle Exit Prompt Keys using generic letters instead of just xbox keys
        if (showExitPrompt) {
          if (e.key === 'a' || e.key === 'A' || e.key === 'Enter') {
            setShowExitPrompt(false);
            handleSave();
          } else if (e.key === 'b' || e.key === 'B' || e.key === 'x' || e.key === 'X' || e.key === 'Escape' || e.key === 'Backspace') {
            setShowExitPrompt(false);
            executeBackout();
          }
        }
        return;
      }

      // Handle Ctrl+S globally
      if ((e.ctrlKey || e.metaKey) && (e.key === 's' || e.key === 'S')) {
        e.preventDefault();
        e.stopPropagation();
        handleSave();
        return;
      }

      // Ignore standard key bindings if user is focused on an input or textarea
      if (document.activeElement && (document.activeElement.tagName === 'INPUT' || document.activeElement.tagName === 'TEXTAREA')) {
        if (e.key === 'Escape') {
          document.activeElement.blur();
        }
        return; // Let the input type naturally
      }

      e.stopPropagation();

      switch (e.key) {
        case 'ArrowUp':
          playSound('focus');
          setSelectedIndex(prev => (prev > 0 ? prev - 1 : dynamicSettingsItems.length - 1));
          break;
        case 'ArrowDown':
          playSound('focus');
          setSelectedIndex(prev => (prev < dynamicSettingsItems.length - 1 ? prev + 1 : 0));
          break;
        case 'q': // LB
          playSound('focus');
          setSelectedIndex(prev => (prev > 0 ? prev - 1 : dynamicSettingsItems.length - 1));
          break;
        case 'e': // RB
          playSound('focus');
          setSelectedIndex(prev => (prev < dynamicSettingsItems.length - 1 ? prev + 1 : 0));
          break;
        case 'x':
          handleSave();
          break;
        case 'y':
          handleDefault();
          break;
        case 'Enter':
          playSound('select');
          if (dynamicSettingsItems[selectedIndex].id === 'country') {
            setActivePanel('country');
          } else if (dynamicSettingsItems[selectedIndex].id === 'core') {
            setActivePanel('core');
          } else if (dynamicSettingsItems[selectedIndex].id === 'ports') {
            setActivePanel('ports');
          } else if (dynamicSettingsItems[selectedIndex].id === 'help') {
            setActivePanel('help');
          } else if (dynamicSettingsItems[selectedIndex].id === 'color') {
            setActivePanel('color');
          } else if (dynamicSettingsItems[selectedIndex].id === 'account') {
            setActivePanel('account');
          } else if (dynamicSettingsItems[selectedIndex].id === 'about') {
            setActivePanel('about');
          }
          break;
        case 'Escape':
        case 'Backspace':
          e.preventDefault();
          e.stopImmediatePropagation(); // Prevent dashboard from seeing this
          attemptExit();
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown, true);
    return () => window.removeEventListener('keydown', handleKeyDown, true);
  }, [isActive, selectedIndex, onBack, activePanel, isSaving, isDirty, showExitPrompt]);

  const selectedRef = useRef(selectedIndex);
  const activePanelRef = useRef(activePanel);
  useEffect(() => { selectedRef.current = selectedIndex; }, [selectedIndex]);
  useEffect(() => { activePanelRef.current = activePanel; }, [activePanel]);

  useEffect(() => {
    if (!isActive || isSaving || showExitPrompt) {
      if (showExitPrompt) {
        const unsub = onGamepadPress((event) => {
          if (event.type !== 'press') return;
          if (event.button === 'a') {
            setShowExitPrompt(false);
            handleSave();
          } else if (event.button === 'b' || event.button === 'x' || event.button === 'y') {
            setShowExitPrompt(false);
            executeBackout();
          }
        });
        return unsub;
      }
      return;
    }
    
    const unsub = onGamepadPress((event) => {
      if (event.type !== 'press') return;

      if (activePanelRef.current) {
        if (activePanelRef.current === 'country' || activePanelRef.current === 'core' || activePanelRef.current === 'ports' || activePanelRef.current === 'color' || activePanelRef.current === 'help' || activePanelRef.current === 'about') return;

        if (event.button === 'b') {
          playSound('back');
          setActivePanel(null);
        }
        return;
      }

      if (event.button === 'dpadUp' || event.button === 'stickUp') {
        playSound('focus');
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : dynamicSettingsItems.length - 1));
      }
      if (event.button === 'dpadDown' || event.button === 'stickDown') {
        playSound('focus');
        setSelectedIndex(prev => (prev < dynamicSettingsItems.length - 1 ? prev + 1 : 0));
      }
      if (event.button === 'lb') {
        playSound('focus');
        setSelectedIndex(prev => (prev > 0 ? prev - 1 : dynamicSettingsItems.length - 1));
      }
      if (event.button === 'rb') {
        playSound('focus');
        setSelectedIndex(prev => (prev < dynamicSettingsItems.length - 1 ? prev + 1 : 0));
      }
      // Save button: Square for PlayStation, X for Xbox/Nintendo
      const controllerType = localStorage.getItem('controllerType') || 'xbox';
      if (controllerType === 'playstation' && event.button === 'square') {
        handleSave();
      } else if (controllerType !== 'playstation' && event.button === 'x') {
        handleSave();
      }
      if (event.button === 'y') {
        handleDefault();
      }
      if (event.button === 'a') {
        playSound('select');
        const currentItem = dynamicSettingsItems[selectedRef.current];
        if (currentItem && currentItem.id === 'country') {
          setActivePanel('country');
        } else if (currentItem && currentItem.id === 'core') {
          setActivePanel('core');
        } else if (currentItem && currentItem.id === 'ports') {
          setActivePanel('ports');
        } else if (currentItem && currentItem.id === 'help') {
          setActivePanel('help');
        } else if (currentItem && currentItem.id === 'color') {
          setActivePanel('color');
        } else if (currentItem && currentItem.id === 'account') {
          setActivePanel('account');
        }
      }
      if (event.button === 'b') {
        attemptExit();
      }
    });
    return unsub;
  }, [isActive, onGamepadPress, onBack, isSaving, isDirty, showExitPrompt]);

  useEffect(() => {
    if (listRef.current) {
      const el = listRef.current.children[selectedIndex];
      if (el) el.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }
  }, [selectedIndex]);

  if (!isActive) return null;

  const currentItem = dynamicSettingsItems[selectedIndex];

  return (
    <div className="settings-container" data-testid="settings">
      <div className="settings-title">Settings</div>

      <div className="settings-body">
        {/* Saving Overlay */}
        {isSaving && (
          <div className="settings-loading-overlay">
            {saveStatus === 'saving' ? (
              <div className="settings-dialog-box animate-scale-in">
                <div className="settings-spinner"></div>
                <div className="settings-saving-text">Please Wait... Saving</div>
                <div className="settings-saving-subtext">Do not turn off your system.</div>
              </div>
            ) : (
              <div className="settings-dialog-box animate-scale-in">
                <div className="settings-saving-text" style={{ color: '#107C10' }}>Done Saving!</div>
                <div className="settings-saving-subtext" style={{ marginBottom: '20px' }}>The settings have been applied successfully.</div>

                <button
                  className="settings-confirm-btn"
                  onClick={handleRestart}
                  autoFocus
                >
                  OK (RESTART)
                </button>
              </div>
            )}
          </div>
        )}

        {/* Exit Prompt Overlay */}
        {showExitPrompt && (
          <div className="settings-loading-overlay animate-scale-in" style={{ zIndex: 9999, backgroundColor: 'rgba(0, 0, 0, 0.7)' }}>
            <div className="settings-dialog-box" style={{ 
              width: '460px', 
              background: '#252526', 
              border: '1px solid #454545',
              boxShadow: '0 8px 32px rgba(0,0,0,0.8)',
              padding: '24px',
              borderRadius: '4px',
              textAlign: 'left'
            }}>
              <div style={{ display: 'flex', alignItems: 'flex-start', marginBottom: '24px' }}>
                <AlertCircle size={32} color="#007acc" style={{ marginRight: '16px', flexShrink: 0 }} />
                <div>
                  <div style={{ fontSize: '18px', fontWeight: '500', color: '#ffffff', marginBottom: '8px', fontFamily: '"Segoe UI", system-ui, sans-serif' }}>
                    Unsaved Settings
                  </div>
                  <div style={{ fontSize: '14px', color: '#cccccc', lineHeight: '1.5', fontFamily: '"Segoe UI", system-ui, sans-serif' }}>
                    You have modified configurations that have not been applied. Do you want to apply your changes before exiting?
                  </div>
                </div>
              </div>
              
              <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end', marginTop: '10px' }}>
                <button
                  className="settings-confirm-btn"
                  style={{ background: '#007acc', color: '#ffffff', minWidth: '90px', padding: '6px 16px', fontSize: '14px', borderRadius: '4px', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                  onClick={() => { setShowExitPrompt(false); handleSave(); }}
                >
                  <div className="xbox-btn-circle green" style={{ marginRight: '8px', transform: 'scale(0.8)' }}>A</div> Apply
                </button>
                <button
                  className="settings-confirm-btn"
                  style={{ background: '#3e3e42', color: '#ffffff', minWidth: '90px', padding: '6px 16px', fontSize: '14px', borderRadius: '4px', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                  onClick={() => { setShowExitPrompt(false); executeBackout(); }}
                >
                  <div className="xbox-btn-circle red" style={{ marginRight: '8px', transform: 'scale(0.8)' }}>B</div> Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Left: Sidebar */}
        <div className="settings-sidebar" ref={listRef}>
          {dynamicSettingsItems.map((item, index) => (
            <div
              key={item.id}
              className={`settings-sidebar-item ${selectedIndex === index ? 'active' : ''} ${activePanel === item.id ? 'entered' : ''}`}
              onClick={() => {
                playSound('select');
                setSelectedIndex(index);
                setActivePanel(item.id);
              }}
              onMouseEnter={() => {
                if (!activePanel) setSelectedIndex(index);
              }}
            >
              <item.icon size={20} className="settings-sidebar-icon" />
              <span className="settings-sidebar-label">{item.label}</span>
              {item.badge && <span className="settings-sidebar-badge">{item.badge}</span>}
            </div>
          ))}
        </div>

        {/* Right: Content Pane */}
        <div className="settings-content-pane" data-testid="settings-content-pane" style={{ padding: '30px 36px', overflow: 'hidden' }}>
            <div className="settings-content-inner">
              <h2 className="settings-content-title">{dynamicSettingsItems[selectedIndex].label}</h2>
              {dynamicSettingsItems[selectedIndex].id !== 'about' && (
                <p className="settings-content-desc">{dynamicSettingsItems[selectedIndex].description}</p>
              )}

              <div className={`settings-preview-mount ${activePanel ? 'deep-focus' : ''}`}>
                {dynamicSettingsItems[selectedIndex].id === 'account' && (
                  <AccountSettings 
                    isActive={activePanel === 'account'} 
                    userProfile={userProfile} 
                    isLoggedIn={isLoggedIn} 
                    onLogout={onLogout} 
                    onBack={() => { playSound('back'); setActivePanel(null); }} 
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'controller' && (
                  <ControllerSettings 
                    isActive={activePanel === 'controller'} 
                    onBack={() => { playSound('back'); setActivePanel(null); }} 
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'core' && (
                  <CoreSettings preview={true} isActive={activePanel === 'core'} onBack={() => { playSound('back'); setActivePanel(null); }} />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'ports' && (
                  <PortsSettings preview={true} isActive={activePanel === 'ports'} onBack={() => { playSound('back'); setActivePanel(null); }} />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'country' && (
                  <LanguageSettings
                    preview={true}
                    isActive={activePanel === 'country'}
                    activeCountry={countryCode}
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                    onSelect={(v) => {
                      setCountryCode(v.code);
                      setIsDirty(true);
                    }}
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'color' && (
                  <ColorSettings 
                    preview={true} 
                    isActive={activePanel === 'color'} 
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                    onColorChange={() => setIsDirty(true)}
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'background' && (
                  <BackgroundSettings
                    preview={true}
                    isActive={activePanel === 'background'}
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                    onDirty={() => setIsDirty(true)}
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'help' && (
                  <HelpSettings
                    preview={activePanel !== 'help'}
                    isActive={activePanel === 'help'}
                    userProfile={userProfile}
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'contributors' && (
                  <ContributorsSettings
                    preview={activePanel !== 'contributors'}
                    isActive={activePanel === 'contributors'}
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                  />
                )}
                {dynamicSettingsItems[selectedIndex].id === 'about' && (
                  <AboutSettings
                    preview={activePanel !== 'about'}
                    isActive={activePanel === 'about'}
                    onBack={() => { playSound('back'); setActivePanel(null); }}
                  />
                )}
              </div>
            </div>
        </div>

      </div>

      {/* Footer */}
      <div className="settings-footer" data-testid="settings-footer">
        <div className="settings-footer-item" style={{ cursor: 'default' }}>
          {controllerType === 'playstation' ? (
            <>
              <div className="xbox-btn-bumper">L1</div>
              <div className="xbox-btn-bumper">R1</div>
            </>
          ) : controllerType === 'nintendo' ? (
            <>
              <div className="xbox-btn-bumper">ZL</div>
              <div className="xbox-btn-bumper">ZR</div>
            </>
          ) : controllerType === 'generic' ? (
            <>
              <div className="xbox-btn-bumper">L1</div>
              <div className="xbox-btn-bumper">R1</div>
            </>
          ) : (
            <>
              <div className="xbox-btn-bumper">LB</div>
              <div className="xbox-btn-bumper">RB</div>
            </>
          )}
          <span>Tabs</span>
        </div>
        {dynamicSettingsItems[selectedIndex].id === 'core' && (
          <div className="settings-footer-item" onClick={handleSave} style={{ cursor: 'pointer' }}>
            {controllerType === 'playstation' ? (
              <div className="xbox-btn-circle" style={{ color: '#E91E63' }}>□</div>
            ) : controllerType === 'nintendo' ? (
              <div className="xbox-btn-circle" style={{ color: '#fff' }}>Y</div>
            ) : controllerType === 'generic' ? (
              <div className="xbox-btn-circle" style={{ color: '#fff' }}>4</div>
            ) : (
              <div className="xbox-btn-circle blue">X</div>
            )}
            <span>Save</span>
          </div>
        )}
        {dynamicSettingsItems[selectedIndex].id === 'core' && (
          <div className="settings-footer-item" onClick={handleDefault} style={{ cursor: 'pointer' }}>
            {controllerType === 'playstation' ? (
              <div className="xbox-btn-circle" style={{ color: '#27AE60' }}>△</div>
            ) : controllerType === 'nintendo' ? (
              <div className="xbox-btn-circle" style={{ color: '#fff' }}>X</div>
            ) : controllerType === 'generic' ? (
              <div className="xbox-btn-circle" style={{ color: '#fff' }}>3</div>
            ) : (
              <div className="xbox-btn-circle yellow">Y</div>
            )}
            <span>Default</span>
          </div>
        )}
        <div className="settings-footer-item" onClick={() => {
          playSound('select');
          if (dynamicSettingsItems[selectedIndex].id === 'country') {
            setActivePanel('country');
          } else if (dynamicSettingsItems[selectedIndex].id === 'core') {
            setActivePanel('core');
          } else if (dynamicSettingsItems[selectedIndex].id === 'ports') {
            setActivePanel('ports');
          } else if (dynamicSettingsItems[selectedIndex].id === 'help') {
            setActivePanel('help');
          } else if (dynamicSettingsItems[selectedIndex].id === 'color') {
            setActivePanel('color');
          } else if (dynamicSettingsItems[selectedIndex].id === 'account') {
            setActivePanel('account');
          } else if (dynamicSettingsItems[selectedIndex].id === 'controller') {
            setActivePanel('controller');
          } else if (dynamicSettingsItems[selectedIndex].id === 'contributors') {
            setActivePanel('contributors');
          } else if (dynamicSettingsItems[selectedIndex].id === 'about') {
            setActivePanel('about');
          }
        }} style={{ cursor: 'pointer' }}>
          {controllerType === 'playstation' ? (
            <div className="xbox-btn-circle" style={{ color: '#0070CC' }}>✕</div>
          ) : controllerType === 'nintendo' ? (
            <div className="xbox-btn-circle" style={{ color: '#fff' }}>B</div>
          ) : controllerType === 'generic' ? (
            <div className="xbox-btn-circle" style={{ color: '#fff' }}>2</div>
          ) : (
            <div className="xbox-btn-circle green">A</div>
          )}
          <span>Select</span>
        </div>
        <div className="settings-footer-item" onClick={attemptExit} style={{ cursor: 'pointer' }}>
          {controllerType === 'playstation' ? (
            <div className="xbox-btn-circle" style={{ color: '#CD2A2A' }}>○</div>
          ) : controllerType === 'nintendo' ? (
            <div className="xbox-btn-circle" style={{ color: '#fff' }}>A</div>
          ) : controllerType === 'generic' ? (
            <div className="xbox-btn-circle" style={{ color: '#fff' }}>1</div>
          ) : (
            <div className="xbox-btn-circle red">B</div>
          )}
          <span>{activePanel ? 'Back to Settings' : 'Back to Dashboard'}</span>
        </div>
      </div>
    </div>
  );
};

export default Settings;
